import{_ as a,o as n,c as o,a4 as t}from"./chunks/framework.BisFRKAV.js";const h=JSON.parse('{"title":"About Xu Hongduo","description":"LLM deployment and platform engineering, with continuing study of model fundamentals, inference systems and training methods.","frontmatter":{"layout":"page","title":"About Xu Hongduo","description":"LLM deployment and platform engineering, with continuing study of model fundamentals, inference systems and training methods.","kind":"about","status":"published","contentLang":"en","translations":{"zh":"/about"},"sidebar":false,"aside":false,"outline":false},"headers":[],"relativePath":"en/about.md","filePath":"en/about.md"}'),i={name:"en/about.md"};function s(r,e,l,d,p,u){return n(),o("div",null,[...e[0]||(e[0]=[t('<div class="profile-page"><header class="profile-header"><p class="profile-overline" lang="en">About</p><h1 id="profile" tabindex="-1">Xu Hongduo <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Xu Hongduo {#profile}&quot;">​</a></h1><p class="profile-bio">I work on LLM deployment and model management platforms. Questions about latency, resources and reliability led me to trace how models generate, how training changes outputs, and how experiments locate the source of a change.</p><nav class="profile-links" aria-label="Author links"><a href="/en/articles/">Published articles <span aria-hidden="true">→</span></a><a href="https://github.com/xhongduo-tech" target="_blank" rel="noopener noreferrer">GitHub <span aria-hidden="true">↗</span></a></nav></header><section class="profile-section" aria-labelledby="profile-interests"><h2 id="profile-interests" tabindex="-1">Areas of interest <a class="header-anchor" href="#profile-interests" aria-label="Permalink to &quot;Areas of interest {#profile-interests}&quot;">​</a></h2><ul class="profile-focus"><li><h3>Inference algorithms and serving</h3><p>Tracing decoding, KV caches and request scheduling from the state of a single generation.</p></li><li><h3>Training and post-training</h3><p>Following label positions, parameter updates and behavioral changes on held-out examples.</p></li><li><h3>Model and systems evaluation</h3><p>Comparing example-level differences and investigating improvements, regressions and evaluation conditions.</p></li></ul></section><section class="profile-section" aria-labelledby="profile-notebook"><h2 id="profile-notebook" tabindex="-1">About this site <a class="header-anchor" href="#profile-notebook" aria-label="Permalink to &quot;About this site {#profile-notebook}&quot;">​</a></h2><p>This blog addresses specific LLM questions. Articles retain derivations, relevant source references, reproducible examples and conclusion boundaries.</p><p>The detailed learning map and annual tasks remain private. Projects become public only after real records exist. Measurements identify model versions, inputs, configurations and environments; paper results are never presented as personal measurements.</p><nav class="profile-links" aria-label="Site links"><a href="/en/articles/#topology-heading">Domain topology <span aria-hidden="true">→</span></a><a href="https://github.com/xhongduo-tech/xhongduo-tech.github.io" target="_blank" rel="noopener noreferrer">Source code <span aria-hidden="true">↗</span></a></nav></section></div>',1)])])}const f=a(i,[["render",s]]);export{h as __pageData,f as default};
